fn tables() -> Option<Tables> {
    let path = std::env::var("GAME_DLL").ok()?;
    let bytes = std::fs::read(path).ok()?;
    Tables::from_game_dll(&bytes).ok()
}

#[test]
fn life_sink_matches_the_original_bit_for_bit_on_valid_states() {
    let Some(t) = tables() else {
        return;
    };
    let mut bad = Vec::new();
    for (i, &(flags, before, delta, mode, after)) in VECTORS.iter().enumerate() {
        let mut c = LifeCells {
            life: F32::from_bits(before[0]),
            floor: F32::from_bits(before[1]),
            max: F32::from_bits(before[2]),
        };
        life_sink(&mut c, flags & 0x100 != 0, F32::from_bits(delta), mode, Some(&t));
        let got = [c.life.to_bits(), c.floor.to_bits(), c.max.to_bits()];
        if got != after {
            bad.push(format!("case {i}: got {got:08x?} want {after:08x?}"));
        }
    }
    assert!(bad.is_empty(), "{} mismatches, first: {:?}", bad.len(), bad.first());
    let zero_results = VECTORS.iter().filter(|r| r.4[0] & 0x7fff_ffff == 0).count();
    eprintln!("life sink: {} cases bit-exact, {zero_results} with a zero life result", VECTORS.len());
}
